        + 4 * size_of::<Frame<'static>>()
        + 4 * size_of::<Option<Frame<'static>>>()
        + 4 * size_of::<Option<&SkeletonObservation>>()
        + 4 * size_of::<Result<(), Diagnostic>>()
        + size_of::<Result<Option<&SkeletonObservation>, Diagnostic>>()
        + 10 * size_of::<usize>()
        + 8 * size_of::<bool>()
